package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import org.json.*;
public class Review0525Test {
 @Test public void trailingLibrarySlashPreservesCardRoot(){for(String root:List.of("/video/Series","/video/Series/","/video/Series///")){assertEquals("/video/Series/Samples",MediaLogic.cardRoot(root,"/video/Series/Samples/S01E01.mkv"));assertFalse(MediaLogic.samplePath("/video/Series/Samples/S01E01.mkv",MediaLogic.cardRoot(root,"/video/Series/Samples/S01E01.mkv"),false,false));assertTrue(MediaLogic.samplePath("/video/Series/Show/Samples/clip.mkv",MediaLogic.cardRoot(root,"/video/Series/Show/Samples/clip.mkv"),false,false));}}
 @Test public void ambiguousSamplePrefixNeedsSizeEvidence(){for(String name:List.of("Sample-The.Movie.2019.mkv","sample_movie.mkv")){assertFalse(MediaLogic.sample(name));assertFalse(MediaLogic.sample(name,MediaLogic.SAMPLE_MAX_BYTES,-1));assertFalse(MediaLogic.sample(name,MediaLogic.SAMPLE_MAX_BYTES+1,-1));assertTrue(MediaLogic.sample(name,200000000L,2000000001L));assertFalse(MediaLogic.sample(name,200000000L,2000000000L));assertFalse(MediaLogic.sample(name,-1,99999999999L));}assertFalse(MediaLogic.sample("Sample Size.mkv",2000000000L,2000000000L));assertTrue(MediaLogic.sample("Movie.sample.mkv"));}
 @Test public void torrentSelectionUsesActualFolderAndKeepsNfo()throws Exception{JSONArray files=new JSONArray().put(new JSONObject().put("name","A/main.mkv").put("size",3000000000L)).put(new JSONObject().put("name","A/sample_movie.mkv").put("size",200000000L)).put(new JSONObject().put("name","B/sample_movie.mkv").put("size",200000000L)).put(new JSONObject().put("name","A/release.nfo").put("size",10));Map<String,Long> sizes=DownloadStation.torrentVideoSizes(files);assertFalse(DownloadStation.defaultSelected(files.getJSONObject(1),"",sizes));assertTrue(DownloadStation.defaultSelected(files.getJSONObject(2),"",sizes));assertTrue(DownloadStation.defaultSelected(files.getJSONObject(3),"",sizes));assertTrue(DownloadStation.defaultSelected(new JSONObject().put("name","A/sample_unknown.mkv"),"",sizes));}
 @Test public void listingSizeEvidenceIsSharedByScanningAndDeletion(){NasClient.Entry main=new NasClient.Entry("main.mkv","/video/Movie/main.mkv",false,3000000000L),clip=new NasClient.Entry("Sample-Movie.mkv","/video/Movie/Sample-Movie.mkv",false,200000000L);long largest=MediaLogic.largestVideoSize(List.of(main,clip));assertFalse(MediaLogic.sampleEntry(main,largest));assertTrue(MediaLogic.sampleEntry(clip,largest));clip.sizeKnown=false;assertFalse(MediaLogic.sampleEntry(clip,largest));}
 @Test public void samplePrefixDoesNotLeaveOrphanMovieFolder()throws Exception{String root=MediaDeletionTest.ROOT,main=root+"/Movie/Main.mkv",clip=root+"/Movie/Sample-Movie.mkv",nfo=root+"/Movie/release.nfo";MediaDeletionTest.Files fs=new MediaDeletionTest.Files(main,clip,nfo);NasClient.Entry m=fs.rows.get(main),c=fs.rows.get(clip);NasClient.Entry big=new NasClient.Entry(m.name,m.path,false,3000000000L);big.realPath=m.realPath;fs.rows.put(main,big);NasClient.Entry small=new NasClient.Entry(c.name,c.path,false,100000000L);small.realPath=c.realPath;fs.rows.put(clip,small);MediaDeletion inv=new MediaDeletionTest().movie(fs,main);MediaDeletion.Plan plan=inv.plan(null);assertTrue(plan.files.contains(clip));assertTrue(plan.files.contains(nfo));inv.execute(plan,fs);assertFalse(fs.rows.containsKey(root+"/Movie"));}
 @Test public void actualLibraryScanSkipsSmallPrefixSamplesButKeepsLargeTitle()throws Exception{
  List<NasClient.Entry> rows=List.of(new NasClient.Entry("Main.mkv","/movies/Main.mkv",false,3000000000L),new NasClient.Entry("Sample-Movie.mkv","/movies/Sample-Movie.mkv",false,200000000L),new NasClient.Entry("Sample Size.mkv","/movies/Sample Size.mkv",false,400000000L));
  Library.Source source=new Library.Source(){public List<NasClient.Entry> list(String path){return rows;}public byte[] readFile(String path,int limit)throws Exception{throw new java.io.IOException("No NFO in fixture");}};
  Library library=new Library(source,(endpoint,params)->new JSONObject().put("results",new JSONArray()));
  List<Library.Card> cards=library.scan("/movies",true,n->{});assertEquals(2,cards.size());assertTrue(cards.stream().noneMatch(c->c.path.endsWith("Sample-Movie.mkv")));assertTrue(cards.stream().anyMatch(c->c.path.endsWith("Sample Size.mkv")));
 }
}
